```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An ontology of securities, debt/equity/hybrid instruments, derivatives and funds, modelled from a general corpus on financial securities." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties; per IAS 32, any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:FinancialAsset a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "financial asset" ;
    rdfs:comment "Cash, a contractual right to receive cash or another financial instrument, a contractual right to exchange financial instruments under potentially favourable conditions, or an equity instrument of another entity." .

fis:FinancialLiability a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "financial liability" ;
    rdfs:comment "A legal obligation to deliver cash or another financial instrument to another entity, or to exchange financial instruments under potentially unfavourable conditions." .

fis:Underlier a owl:Class ;
    rdfs:label "underlier" ;
    rdfs:comment "An item (the underlier/underlying asset) that can or must be bought or sold, or referenced, as the basis of a derivative or convertible instrument: a commodity, financial instrument, price index, currency, interest rate, or similar reference." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

fis:Commodity a owl:Class ;
    rdfs:subClassOf fis:Underlier ;
    rdfs:label "commodity" .

fis:Index a owl:Class ;
    rdfs:subClassOf fis:Underlier ;
    rdfs:label "index" ;
    rdfs:comment "A price index, stock index or other benchmark index that can serve as an underlier or be tracked by a fund." .

fis:Currency a owl:Class ;
    rdfs:subClassOf fis:Underlier ;
    rdfs:label "currency" .

fis:InterestRateBenchmark a owl:Class ;
    rdfs:subClassOf fis:Underlier ;
    rdfs:label "interest rate benchmark" ;
    rdfs:comment "A reference interest rate such as LIBOR, EURIBOR or SOFR used to set floating payments." .

fis:Mortgage a owl:Class ;
    rdfs:subClassOf fis:Underlier ;
    rdfs:label "mortgage" .

fis:Dividend a owl:Class ;
    rdfs:label "dividend" ;
    rdfs:comment "A discretionary portion of a company's profit paid to shareholders; declared by the board rather than contractually fixed." .

fis:Issuer a owl:Class ;
    rdfs:label "issuer" ;
    rdfs:comment "The company or other entity obligated on, and that issues, a security or other financial instrument." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "sovereign government" .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "local government" ; rdfs:comment "A state, provincial, territorial, municipal or other sub-sovereign governmental unit." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "supranational organization" ; rdfs:comment "E.g. the World Bank, the IMF, or a regional development bank." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "corporation" .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Corporation ; rdfs:label "bank" .

:AllDisjointIssuers a owl:AllDisjointClasses ;
    owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation ) .

fis:RevenueSource a owl:Class ; rdfs:label "revenue source" .
fis:TaxRevenue a owl:Class ; rdfs:subClassOf fis:RevenueSource ; rdfs:label "tax revenue" ; rdfs:comment "General taxing power backing a general obligation bond." .
fis:ProjectRevenue a owl:Class ; rdfs:subClassOf fis:RevenueSource ; rdfs:label "project revenue" ; rdfs:comment "Revenue generated by a specific revenue-generating entity, e.g. a toll road or utility." .
fis:TaxRevenue owl:disjointWith fis:ProjectRevenue .

fis:CreditRating a owl:Class ; rdfs:label "credit rating" .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating ; rdfs:label "investment grade rating" ; rdfs:comment "Ratings AAA, AA, A and BBB." .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRating ; rdfs:label "high-yield rating" ; rdfs:comment "Ratings BB and below (junk)." .
fis:InvestmentGradeRating owl:disjointWith fis:HighYieldRating .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security ;
    rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Underlier ;
    rdfs:label "has underlying" ;
    rdfs:comment "Relates a derivative, convertible instrument or warrant to the underlier whose value or shares it references." .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlier ;
    rdfs:range fis:FinancialInstrument ;
    rdfs:label "is underlying of" .

fis:hasEmbeddedOption a owl:ObjectProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Option ;
    rdfs:label "has embedded option" .

fis:isEmbeddedOptionOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasEmbeddedOption ;
    rdfs:domain fis:Option ;
    rdfs:range fis:Bond ;
    rdfs:label "is embedded option of" .

fis:hasCreditRating a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:CreditRating ;
    rdfs:label "has credit rating" .

fis:isCreditRatingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCreditRating ;
    rdfs:domain fis:CreditRating ;
    rdfs:range fis:Security ;
    rdfs:label "is credit rating of" .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:Issuer ;
    rdfs:label "has reference entity" .

fis:isReferenceEntityOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasReferenceEntity ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:CreditDefaultSwap ;
    rdfs:label "is reference entity of" .

fis:hasTrackedIndex a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:IndexFund ;
    rdfs:range fis:Index ;
    rdfs:label "has tracked index" .

fis:isTrackedIndexOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasTrackedIndex ;
    rdfs:domain fis:Index ;
    rdfs:range fis:IndexFund ;
    rdfs:label "is tracked index of" .

fis:hasPortfolio a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    rdfs:label "has portfolio" ;
    rdfs:comment "Relates a fund to a security held in its pooled portfolio." .

fis:isPortfolioOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasPortfolio ;
    rdfs:domain fis:Security ;
    rdfs:range fis:InvestmentFund ;
    rdfs:label "is portfolio of" .

fis:hasRepaymentSource a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:MunicipalBond ;
    rdfs:range fis:RevenueSource ;
    rdfs:label "has repayment source" .

fis:isRepaymentSourceOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasRepaymentSource ;
    rdfs:domain fis:RevenueSource ;
    rdfs:range fis:MunicipalBond ;
    rdfs:label "is repayment source of" .

fis:hasDividend a owl:ObjectProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:Dividend ;
    rdfs:label "has dividend" .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasTradability a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:FinancialAsset ;
    rdfs:range xsd:boolean ;
    rdfs:label "has tradability" .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:date ;
    rdfs:label "has maturity date" ;
    rdfs:comment "Also referred to as the expiration date for options, futures and forwards." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" ;
    rdfs:comment "Also called par value, nominal value or principal amount." .

fis:hasCouponRate a owl:DatatypeProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" ;
    rdfs:comment "Also referred to as the interest rate on a debt security." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has strike price" .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Swap ;
    rdfs:range xsd:decimal ;
    rdfs:label "has notional amount" .

fis:hasConversionRatio a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has conversion ratio" .

fis:confersVotingRight a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range xsd:boolean ;
    rdfs:label "confers voting right" .

fis:hasDividendRate a owl:DatatypeProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:decimal ;
    rdfs:label "has dividend rate" .

fis:hasCreditRatingSymbol a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:CreditRating ;
    rdfs:range xsd:string ;
    rdfs:label "has credit rating symbol" .

fis:isSecuredByCollateral a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is secured by collateral" .

fis:hasSeniorityRank a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string ;
    rdfs:label "has seniority rank" ;
    rdfs:comment "Value 'senior' or 'subordinated'." .

fis:hasCertificateForm a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string ;
    rdfs:label "has certificate form" ;
    rdfs:comment "Value 'bearer', 'registered' or 'bookEntry'." .

fis:hasDivisibility a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string ;
    rdfs:label "has divisibility" ;
    rdfs:comment "Value 'divided' or 'undivided'." .

fis:hasFungibility a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean ;
    rdfs:label "has fungibility" .

fis:isStandardized a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean ;
    rdfs:label "is standardized" .

fis:hasOptionType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:string ;
    rdfs:label "has option type" ;
    rdfs:comment "Value 'call' or 'put'." .

fis:hasExerciseStyle a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:string ;
    rdfs:label "has exercise style" ;
    rdfs:comment "Value 'american', 'european' or 'bermudan'." .

fis:isExchangeTraded a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range xsd:boolean ;
    rdfs:label "is exchange traded" .

fis:hasReferenceRate a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string ;
    rdfs:label "has reference rate" ;
    rdfs:comment "Name of the money-market reference rate (e.g. SOFR) to which a floating coupon is linked." .

#################################################################
# SECURITY / DEBT / EQUITY / HYBRID
#################################################################

fis:Security a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "security" ;
    rdfs:comment "A tradable financial asset; its legal definition varies by jurisdiction." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:FinancialAsset
            [ a owl:Restriction ; owl:onProperty fis:hasTradability ; owl:hasValue "true"^^xsd:boolean ]
        )
    ] .

fis:DebtSecurity a owl:Class ;
    rdfs:label "debt security" ;
    rdfs:comment "Called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics. Holder entitled to payment of principal and interest." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Security
            [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:someValuesFrom xsd:decimal ]
        )
    ] .

fis:EquitySecurity a owl:Class ;
    rdfs:label "equity security" ;
    rdfs:comment "Also called equity instrument. A share of equity interest in an entity such as the capital stock of a company, trust or partnership; entitles the holder to a residual claim and (usually) to dividends rather than fixed interest." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Security
            [ a owl:Restriction ; owl:onProperty fis:hasDividend ; owl:someValuesFrom fis:Dividend ]
        )
    ] .

fis:HybridSecurity a owl:Class ;
    rdfs:label "hybrid security" ;
    rdfs:comment "Combines some of the characteristics of both debt and equity securities." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:DebtSecurity fis:EquitySecurity )
    ] .

:AllDisjointSecurityFamilies a owl:AllDisjointClasses ;
    owl:members ( fis:DebtSecurity fis:Derivative ) .

:AllDisjointSecurityFamilies2 a owl:AllDisjointClasses ;
    owl:members ( fis:EquitySecurity fis:Derivative ) .

#################################################################
# SECURITY FORM / DIVISIBILITY / FUNGIBILITY
#################################################################

fis:BearerSecurity a owl:Class ;
    rdfs:label "bearer security" ;
    rdfs:comment "Negotiable; entitles the holder to rights merely by possession." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:hasValue "bearer" ] ) ] .

fis:RegisteredSecurity a owl:Class ;
    rdfs:label "registered security" ;
    rdfs:comment "Entitles the holder to rights only if registered on the issuer's or intermediary's security register." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:hasValue "registered" ] ) ] .

fis:BookEntrySecurity a owl:Class ;
    rdfs:label "book-entry security" ;
    rdfs:comment "Non-certificated; exists only in electronic/dematerialized form." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:hasValue "bookEntry" ] ) ] .

:AllDisjointCertificateForms a owl:AllDisjointClasses ;
    owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) .

fis:DividedSecurity a owl:Class ;
    rdfs:label "divided security" ;
    rdfs:comment "Each divided security constitutes a separate asset, legally distinct from each other security in the same issue." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "divided" ] ) ] .

fis:UndividedSecurity a owl:Class ;
    rdfs:label "undivided security" ;
    rdfs:comment "The entire issue makes up a single asset; each security is a fractional part of this undivided whole." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "undivided" ] ) ] .

fis:DividedSecurity owl:disjointWith fis:UndividedSecurity .

fis:FungibleSecurity a owl:Class ;
    rdfs:label "fungible security" ;
    rdfs:comment "All holdings of the security are treated identically and are interchangeable." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue "true"^^xsd:boolean ] ) ] .

#################################################################
# BOND AND SUBTYPES
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "bond" ;
    rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (the coupon), with cash flow timing varying by bond type." .

fis:Debenture a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "debenture" ;
    rdfs:comment "Long maturity (typically at least ten years), typically unsecured." .

fis:Note a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "note" ;
    rdfs:comment "Shorter maturity than a debenture." .

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "money market instrument" ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less; highly liquid ('near cash'). Not classified as a bond." .

fis:Bond owl:disjointWith fis:MoneyMarketInstrument .

fis:CommercialPaper a owl:Class ;
    rdfs:label "commercial paper" ;
    rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days, issued by corporations." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:label "certificate of deposit" ;
    rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ] ) ] .

fis:TreasuryBill a owl:Class ;
    rdfs:label "treasury bill" ;
    rdfs:comment "Zero-coupon short-term government debt, maturing in one year or less." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] .

# --- Bond by issuer type ---

fis:GovernmentBond a owl:Class ;
    rdfs:label "government bond" ;
    rdfs:comment "Also called a treasury bond or sovereign bond; issued by a sovereign national government." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:SupranationalBond a owl:Class ;
    rdfs:label "supranational bond" ;
    rdfs:comment "Also called a 'supra'; issued by a supranational organization such as the World Bank." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:MunicipalBond a owl:Class ;
    rdfs:label "municipal bond" ;
    rdfs:comment "Also known as a muni; issued by a local authority or subdivision within a country." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:CorporateBond a owl:Class ;
    rdfs:label "corporate bond" ;
    rdfs:comment "Issued by a corporation to raise financing; excludes municipal bonds, per the majority/strict corpus definition (sometimes loosely extended to supranational issuers)." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

:AllDisjointBondByIssuer a owl:AllDisjointClasses ;
    owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond ) .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "war bond" ; rdfs:comment "Issued by a government to fund military operations during wartime." .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "climate bond" ; rdfs:comment "Issued to raise finance for climate-mitigation or adaptation projects." .

fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "social impact bond" ; rdfs:comment "Public-sector entities repay private investors after verified improved social outcomes." .

# --- Municipal bond subtypes ---

fis:GeneralObligationBond a owl:Class ;
    rdfs:label "general obligation bond" ;
    rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and its taxing power." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:TaxRevenue ] ) ] .

fis:RevenueBond a owl:Class ;
    rdfs:label "revenue bond" ;
    rdfs:comment "Repaid solely from revenues generated by a specified revenue-generating entity; typically non-recourse." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:ProjectRevenue ] ) ] .

fis:GeneralObligationBond owl:disjointWith fis:RevenueBond .

fis:AssessmentBond a owl:Class ;
    rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "assessment bond" ;
    rdfs:comment "Repayment based on property-tax assessments; generally considered a form of general obligation bond." .

# --- Bond by credit quality ---

fis:InvestmentGradeBond a owl:Class ;
    rdfs:label "investment grade bond" ;
    rdfs:comment "Also called high grade; rated AAA, AA, A or BBB." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:InvestmentGradeRating ] ) ] .

fis:HighYieldBond a owl:Class ;
    rdfs:label "high-yield bond" ;
    rdfs:comment "Also called a junk bond; rated below investment grade (BB and below)." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:HighYieldRating ] ) ] .

fis:InvestmentGradeBond owl:disjointWith fis:HighYieldBond .

# --- Bond by seniority ---

fis:SeniorBond a owl:Class ;
    rdfs:label "senior bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniorityRank ; owl:hasValue "senior" ] ) ] .

fis:SubordinatedBond a owl:Class ;
    rdfs:label "subordinated bond" ;
    rdfs:comment "Lower priority than other bonds of the issuer in liquidation; debt that is not senior." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniorityRank ; owl:hasValue "subordinated" ] ) ] .

fis:SeniorBond owl:disjointWith fis:SubordinatedBond .

# --- Bond by collateral ---

fis:SecuredBond a owl:Class ;
    rdfs:label "secured bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isSecuredByCollateral ; owl:hasValue "true"^^xsd:boolean ] ) ] .

fis:Debenture owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isSecuredByCollateral ; owl:hasValue "false"^^xsd:boolean ] ) ] .

fis:SecuredBond owl:disjointWith fis:Debenture .

fis:CoveredBond a owl:Class ;
    rdfs:subClassOf fis:SecuredBond ;
    rdfs:label "covered bond" ;
    rdfs:comment "Backed by cash flows from mortgages or public-sector assets, which remain on the issuer's balance sheet." .

# --- Asset-backed family ---

fis:AssetBackedSecurity a owl:Class ;
    rdfs:label "asset-backed security" ;
    rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Underlier ] ) ] .

fis:AssetBackedSecurity owl:disjointWith fis:CoveredBond .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:label "mortgage-backed security" ;
    rdfs:comment "An asset-backed security secured by a mortgage or pool of mortgages." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:label "collateralized debt obligation" ;
    rdfs:comment "An asset-backed security backed by debt obligations, often other asset-backed securities." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "residential mortgage-backed security" ; rdfs:comment "Secured by single-family, one- to four-unit real estate." .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "commercial mortgage-backed security" ; rdfs:comment "Secured by commercial and multi-family properties." .
fis:ResidentialMortgageBackedSecurity owl:disjointWith fis:CommercialMortgageBackedSecurity .

# --- Bond by coupon structure ---

fis:ZeroCouponBond a owl:Class ;
    rdfs:label "zero-coupon bond" ;
    rdfs:comment "Also called a discount bond; pays no periodic interest, sold at a discount, redeemed at face value." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] .

fis:FixedRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "fixed rate bond" ;
    rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ;
    rdfs:label "floating rate note" ;
    rdfs:comment "Variable coupon linked to a money-market reference rate, recalculated periodically." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasReferenceRate ; owl:someValuesFrom xsd:string ] ) ] .

fis:FixedRateBond owl:disjointWith fis:FloatingRateNote .
fis:ZeroCouponBond owl:disjointWith fis:FloatingRateNote .
fis:ZeroCouponBond owl:disjointWith fis:FixedRateBond .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "inflation-indexed bond" ;
    rdfs:comment "Also called a linker; principal and interest payments are indexed to a consumer price index." .

fis:PerpetualBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "perpetual bond" ;
    rdfs:comment "Also called a perpetuity or 'perp'; has no maturity date." .

# --- Bond with embedded options ---

fis:CallableBond a owl:Class ;
    rdfs:label "callable bond" ;
    rdfs:comment "Gives the issuer the right to repay the bond before the maturity date." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] .

fis:PutableBond a owl:Class ;
    rdfs:label "putable bond" ;
    rdfs:comment "Also called a retractable bond; gives the holder the right to force early repayment." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "bullet bond" ; rdfs:comment "A straight bond that is neither callable nor putable." .

# --- Bond by certificate form ---

fis:BearerBond a owl:Class ;
    rdfs:label "bearer bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .

fis:RegisteredBond a owl:Class ;
    rdfs:label "registered bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .

fis:BookEntryBond a owl:Class ;
    rdfs:label "book-entry bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BookEntrySecurity ) ] .

:AllDisjointBondForms a owl:AllDisjointClasses ;
    owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) .

#################################################################
# EQUITY SECURITY AND SUBTYPES
#################################################################

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "common stock" ;
    rdfs:comment "Also called ordinary share or voting share. Typically carries voting rights; lowest priority on dividends and liquidation; pure residual claim." .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity, fis:HybridSecurity ;
    rdfs:label "preferred stock" ;
    rdfs:comment "Also called preference share. Senior to common stock but subordinate to bonds; priority on dividends and liquidation; generally considered a hybrid instrument combining debt- and equity-like features; usually non-voting." .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "cumulative preferred stock" ;
    rdfs:comment "Unpaid dividends accumulate as dividends in arrears." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "noncumulative preferred stock" ;
    rdfs:comment "Also called straight preferred stock; passed dividends are lost." .
fis:CumulativePreferredStock owl:disjointWith fis:NoncumulativePreferredStock .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:label "convertible preferred stock" ;
    rdfs:comment "Preferred stock convertible into a fixed number of common shares." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] .

#################################################################
# HYBRID SECURITIES: CONVERTIBLES, WARRANTS, DEPOSITARY RECEIPTS
#################################################################

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "convertible bond" ;
    rdfs:comment "A debt security (also called convertible note or convertible debenture) that the holder can convert into a specified number of shares of the issuer's common stock." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "exchangeable bond" ;
    rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "warrant" ;
    rdfs:comment "Also called equity warrant; an option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:DepositaryReceipt a owl:Class ;
    rdfs:label "depositary receipt" ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, enabling local trading of foreign shares." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American depositary receipt" ; rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European depositary receipt" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "global depositary receipt" .

:AllDisjointDRs a owl:AllDisjointClasses ;
    owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# DERIVATIVES
#################################################################

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "derivative" ;
    rdfs:comment "A contract between a buyer and a seller whose value depends on the performance of an underlier: an item to be bought/sold, a future act, a price, and a future date." .

fis:Forward a owl:Class ;
    rdfs:label "forward" ;
    rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today; not exchange-traded." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue "false"^^xsd:boolean ] ) ] .

fis:Future a owl:Class ;
    rdfs:label "future" ;
    rdfs:comment "A standardized contract to buy or sell an asset at a price agreed today, with delivery and payment at a specified future date; written and traded through a clearing house / exchange." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue "true"^^xsd:boolean ] ) ] .

fis:Forward owl:disjointWith fis:Future .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "option" ;
    rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ;
    rdfs:label "call option" ;
    rdfs:comment "The right (not obligation) to buy the underlying at a fixed price." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] .

fis:PutOption a owl:Class ;
    rdfs:label "put option" ;
    rdfs:comment "The right (not obligation) to sell the underlying at a fixed price." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption a owl:Class ;
    rdfs:label "American option" ;
    rdfs:comment "May be exercised on any trading day on or before expiration." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "american" ] ) ] .

fis:EuropeanOption a owl:Class ;
    rdfs:label "European option" ;
    rdfs:comment "May only be exercised on the expiration date." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "european" ] ) ] .

fis:BermudanOption a owl:Class ;
    rdfs:label "Bermudan option" ;
    rdfs:comment "May be exercised only on specified dates on or before expiration." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "bermudan" ] ) ] .

:AllDisjointOptionStyles a owl:AllDisjointClasses ;
    owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "swap" ;
    rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another, over a notional principal amount that is not itself exchanged." .

fis:InterestRateSwap a owl:Class ;
    rdfs:label "interest rate swap" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRateBenchmark ] ) ] .

fis:CurrencySwap a owl:Class ;
    rdfs:label "currency swap" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:label "credit default swap" ;
    rdfs:comment "The seller compensates the buyer in the event of default or other credit event affecting a reference entity's loan or bond." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] .

:AllDisjointSwapTypes a owl:AllDisjointClasses ;
    owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) .

fis:StockDerivative a owl:Class ;
    rdfs:label "stock derivative" ;
    rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ;
    rdfs:label "investment fund" ;
    rdfs:comment "Pools money from many investors to purchase securities, forming a managed portfolio." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:Security ] ) ] .

fis:MutualFund a owl:Class ;
    rdfs:label "mutual fund" ;
    rdfs:comment "An SEC-registered open-end investment company whose shares transact at next-calculated net asset value rather than on an exchange." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue "false"^^xsd:boolean ] ) ] .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:label "exchange-traded fund" ;
    rdfs:comment "Shares trade on national securities exchanges at market prices that may differ from net asset value." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue "true"^^xsd:boolean ] ) ] .

fis:MutualFund owl:disjointWith fis:ExchangeTradedFund .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "hedge fund" ;
    rdfs:comment "Pools investor money like a mutual fund but with fewer investor-protection regulations and more flexible, riskier strategies; not typically referred to as a mutual fund." .

fis:HedgeFund owl:disjointWith fis:MutualFund .

fis:MoneyMarketFund a owl:Class ;
    rdfs:label "money market fund" ;
    rdfs:comment "Invests primarily in money market instruments and other highly liquid, low-risk short-term securities." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .

fis:IndexFund a owl:Class ;
    rdfs:label "index fund" ;
    rdfs:comment "A passively managed fund that tracks the performance of a particular market index." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:Index ] ) ] .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
    rdfs:label "open-end fund" ;
    rdfs:comment "Shares purchased from or sold to the issuer at net asset value." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
    rdfs:label "closed-end fund" .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund ;
    rdfs:label "unit investment trust" .

:AllDisjointFundStructures a owl:AllDisjointClasses ;
    owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) .
