```turtle
@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "Ontology modelling securities, debt/equity/hybrid instruments, derivatives, and investment funds as described in the supplied corpus." .

#################################################################
# TOP-LEVEL FINANCIAL INSTRUMENT HIERARCHY
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled; or, under IAS 32/39, any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "A financial instrument whose value is determined directly by the markets, such as securities, loans and deposits." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" ;
  rdfs:comment "A contract whose value is derived from the performance of an underlying item (commodity, financial instrument, index, currency or interest rate). Note: a US securities-law passage classifies derivatives as a category of 'security' alongside debt and equity securities, conflicting with the dominant corpus framing (adopted here) in which derivatives are a distinct category from cash instruments/securities. Also fails the IFRS 9 'solely payments of principal and interest' (SPPI) test and is therefore measured at fair value through profit or loss." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:FinancialInstrument ]
      [ a owl:Restriction ; owl:onProperty fis:hasExpirationDate ; owl:someValuesFrom xsd:date ]
    )
  ] .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "loan" ;
  rdfs:comment "A cash instrument such as a loan or deposit where both borrower and lender have to agree on a transfer, unlike readily transferable securities." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "deposit" .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset; legal definitions vary by jurisdiction." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue true ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .
owl:AllDisjointClasses [ owl:members ( fis:Security fis:Loan fis:Deposit ) ] .

#################################################################
# SECURITY DICHOTOMIES
#################################################################

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "bearer security" ;
  rdfs:comment "Entitles the holder to rights under the security merely by holding it; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "registered security" ;
  rdfs:comment "Entitles the holder to rights only if they appear on a security register maintained by the issuer or an intermediary." .
owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "certificated security" .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "non-certificated security" ;
  rdfs:comment "Securities in electronic (dematerialised) or 'book entry only' form." .
owl:AllDisjointClasses [ owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) ] .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "divided security" ;
  rdfs:comment "Each divided security constitutes a separate asset legally distinct from every other security in the issue." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "undivided security" ;
  rdfs:comment "The entire issue makes up one single asset; each security is a fractional part of the undivided whole." .
owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "fungible security" ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "non-fungible security" .
owl:AllDisjointClasses [ owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) ] .

fis:PrivatelyPlacedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "privately placed security" ;
  rdfs:comment "Offered privately to a limited number of qualified persons; not publicly tradable." .
fis:PubliclyOfferedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "publicly offered security" .
owl:AllDisjointClasses [ owl:members ( fis:PrivatelyPlacedSecurity fis:PubliclyOfferedSecurity ) ] .

#################################################################
# DEBT / EQUITY / HYBRID SECURITY
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "debt security" ;
  rdfs:comment "The holder is entitled to payment of principal and interest; may be called debentures, bonds, deposits, notes or commercial paper." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasResidualClaim ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
    )
  ] .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "equity security" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; in bankruptcy shares only in the residual interest of the issuer after creditors are paid." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasResidualClaim ; owl:hasValue true ]
    )
  ] .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "Combines some characteristics of both debt and equity securities, e.g. preference shares, convertibles, equity warrants. Under IAS 32, compound instruments such as convertible bonds must have their liability and equity components separated and presented separately." .

#################################################################
# ISSUER / HOLDER
#################################################################

fis:Issuer a owl:Class ; rdfs:label "issuer" ;
  rdfs:comment "The company or other entity issuing a security." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "Local authority or subdivision within a country, e.g. a city or federal state." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Issuer .
owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation fis:Bank ) ] .

fis:Holder a owl:Class ; rdfs:label "holder" .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .

fis:MarketIndex a owl:Class ; rdfs:label "market index" .
fis:StockExchange a owl:Class ; rdfs:label "stock exchange" ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .

fis:Asset a owl:Class ; rdfs:label "asset" ;
  rdfs:comment "An item of collateral backing a debt security, e.g. mortgages, receivables, loans." .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .
fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "Other debt obligations, often other asset-backed securities, used as CDO collateral." .
fis:ConsumerLoan a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "Auto loans, credit card receivables, student loans, home equity loans, etc." .

#################################################################
# BOND AND SUBCLASSES
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "The issuer owes the holder a debt and is obliged to repay principal at the maturity date plus interest (coupon). Exception: an irredeemable (perpetual) bond has no maturity date." .

fis:GovernmentBond a owl:Class ; rdfs:label "government bond" ;
  rdfs:comment "Also called treasury bond; medium or long term debt security issued by a sovereign national government." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:SupranationalBond a owl:Class ; rdfs:label "supranational bond" ;
  rdfs:comment "Represents the debt of international organisations such as the World Bank or IMF." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:MunicipalBond a owl:Class ; rdfs:label "municipal bond" ;
  rdfs:comment "Issued by state, provincial, territorial, municipal or other local governmental units other than sovereign governments." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:CorporateBond a owl:Class ; rdfs:label "corporate bond" ;
  rdfs:comment "Issued by a corporation to raise financing; strictly excludes municipal bonds." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond ) ] .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and its taxing power." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments; generally a form of general obligation bond." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repaid solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .
owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Issued by a government to fund military operations during wartime." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a government or corporate entity to finance climate mitigation/adaptation projects." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Agreement for public sector entities to pay back private investors after verified improved social outcomes." .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:comment "Also called junk bonds; rated below investment grade (BB and below)." .
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:comment "High-grade bonds rated AAA, AA, A or BBB." .
owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Contractually senior to other unsecured debt; priority in bankruptcy." .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Lower priority than senior bonds in case of liquidation." .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet, unlike asset-backed securities." ;
  owl:disjointWith fis:AssetBackedSecurity .

fis:ConvertibleBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
  rdfs:label "convertible bond" ;
  rdfs:comment "A bond or preferred stock that the holder can convert into the ordinary shares of the issuing company." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer (contrast with ConvertibleBond, whose conversion target is the issuer's own stock)." .

fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par value." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Variable coupon linked to a reference rate such as LIBOR/SOFR/Euribor." .
owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Linker; principal amount and interest payments indexed to the level of consumer prices." .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Also called a perpetuity; has no maturity date." .

fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issuer has the right to repay the bond before the maturity date." .
fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Holder has the right to force the issuer to repay before the maturity date." .

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:FixedRateBond ;
  rdfs:comment "Issuer redeems randomly selected individual bonds within the issue according to a schedule." .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK government bond." .

fis:TreasuryBill a owl:Class ; rdfs:label "treasury bill" ;
  rdfs:comment "Zero-coupon government debt obligation maturing in one year or less." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:GovernmentBond fis:MoneyMarketInstrument ) ] .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Maturity of two, three, five or ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Longest maturity Treasury security, from twenty to thirty years." .
owl:AllDisjointClasses [ owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBond ) ] .

fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:label "Treasury Inflation-Protected Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:GovernmentBond fis:InflationIndexedBond ) ] .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "money market instrument" ;
  rdfs:comment "Short term debt instrument with original maturity of one year or less; highly liquid, sometimes called 'near cash'." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Unsecured promissory note with fixed maturity usually less than 270 days." .
fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Time deposit sold by banks, thrift institutions and credit unions with a specific fixed term." .
fis:JumboCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit, fis:BearerSecurity ;
  rdfs:comment "Negotiable certificate of deposit in bearer form with minimum deposit of $100,000." .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price on a fixed date." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

owl:AllDisjointClasses [ owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:RepurchaseAgreement fis:BankersAcceptance fis:TreasuryBill ) ] .

#################################################################
# ASSET-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "asset-backed security" ;
  rdfs:comment "Umbrella term for a security backed by a pool of assets; narrowly, backed by consumer loans (distinct from MBS/CDO) -- the corpus uses both senses, a conflict noted here; the broad (umbrella) sense is modelled as the genus for MortgageBackedSecurity and CollateralizedDebtObligation." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] .

fis:MortgageBackedSecurity a owl:Class ; rdfs:label "mortgage-backed security" ;
  rdfs:comment "Secured by a mortgage or collection of mortgages." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:label "residential mortgage-backed security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:label "commercial mortgage-backed security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Also called a 'pay-through bond'; divided into tranches with different maturities/priorities." .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Each mortgage payment is split into principal and interest components, which can be separated." .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:label "collateralized debt obligation" ;
  rdfs:comment "A type of structured asset-backed security, sliced into tranches that catch cash flow in sequence based on seniority." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:Stock a owl:Class ; rdfs:label "stock" ;
  rdfs:comment "Partial ownership of a corporation, divided into shares." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:CommonStock a owl:Class ; rdfs:label "common stock" ;
  rdfs:comment "Also called ordinary/voting share; typically carries voting rights (noted exceptions exist, e.g. non-voting common stock)." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "preferred stock" ;
  rdfs:comment "Also called preference shares/preferreds; entitled to a fixed dividend before common stockholders and senior claim on liquidation; generally considered a hybrid instrument. Under IAS 32, a mandatorily redeemable preference share is classified as a financial liability rather than equity, despite its market label." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendRate ; owl:someValuesFrom xsd:decimal ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ; rdfs:label "depositary receipt" ;
  rdfs:comment "Negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
  ) ] .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:label "investment fund" ;
  rdfs:comment "Pools money from many investors to purchase securities; the combined holdings are its portfolio." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:FinancialInstrument ]
  ) ] .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "SEC-registered open-end investment company (terminology used in the US, Canada and India)." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Investors buy and sell ETF shares on national securities exchanges at market prices, which may differ from net asset value." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools money from investors but, unlike mutual funds, has few regulations protecting investors and is available only to high-net-worth individuals." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:HedgeFund fis:ExchangeTradedFund ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:label "money market fund" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:MoneyMarketInstrument ]
  ) ] .

fis:IndexFund a owl:Class ; rdfs:label "index fund" ;
  rdfs:comment "Passively managed fund that tracks the performance of an index." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:MarketIndex ]
  ) ] .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Purchased from or sold to the issuer at net asset value." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

#################################################################
# DERIVATIVES
#################################################################

fis:Forward a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Non-standardized, over-the-counter contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Standardized contract written by a clearing house operating an exchange where the contract can be bought and sold." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:StockFuture a owl:Class ; rdfs:label "stock future" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ]
  ) ] .

fis:Option a owl:Class ; rdfs:label "option" ;
  rdfs:comment "Contract giving the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
  ) ] .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Right to buy at a fixed price." .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Right to sell at a fixed price." .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .
owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Underlying price must pass a barrier level before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "All-or-nothing option paying the full amount if the condition is met at expiration." .

fis:StockOption a owl:Class ; rdfs:label "stock option" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ]
  ) ] .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "A long-dated option, generally traded over the counter." .

fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "equity warrant" ;
  rdfs:comment "Options issued by the company allowing the holder to purchase a specified number of shares at a specified price within a specified time." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Warrant
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
  ) ] .

fis:Swap a owl:Class ; rdfs:label "swap" ;
  rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's, calculated over a notional principal amount." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasNotionalAmount ; owl:someValuesFrom xsd:decimal ]
  ) ] .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:label "credit default swap" ;
  rdfs:comment "Seller compensates the buyer in the event of a loan default or other credit event on a reference entity." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
    [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ]
  ) ] .
owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .
fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Holder .
fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ; rdfs:range fis:FinancialInstrument ;
  rdfs:comment "The asset upon which a derivatives contract is based." .
fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Derivative .

fis:hasConversionTarget a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:EquitySecurity ;
  rdfs:comment "The class of equity shares into which a convertible/exchangeable bond may be converted." .
fis:isConversionTargetOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasConversionTarget ;
  rdfs:domain fis:EquitySecurity ; rdfs:range fis:Bond .

fis:hasTrackedIndex a owl:ObjectProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range fis:MarketIndex .
fis:isTrackedIndexOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasTrackedIndex ;
  rdfs:domain fis:MarketIndex ; rdfs:range fis:InvestmentFund .

fis:hasPortfolioHolding a owl:ObjectProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range fis:FinancialInstrument .
fis:isPortfolioHoldingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasPortfolioHolding ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:InvestmentFund .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer .
fis:isReferenceEntityOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasReferenceEntity ;
  rdfs:domain fis:Issuer ; rdfs:range fis:CreditDefaultSwap .

fis:hasListingVenue a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:StockExchange .
fis:isListingVenueOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasListingVenue ;
  rdfs:domain fis:StockExchange ; rdfs:range fis:Security .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:Asset .
fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ; rdfs:range fis:DebtSecurity .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:isTradable a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:boolean .

fis:hasResidualClaim a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the security confers only a residual claim after all creditor claims are met (equity); false if it confers a fixed debt claim." .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:date ;
  rdfs:comment "The date on which the issuer is obligated to repay the nominal/face amount. Perpetual bonds have no value for this property." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "has face value" ;
  rdfs:comment "Nominal, principal, par or face amount on which the issuer pays interest and which is repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate the issuer pays the holder." .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
  rdfs:comment "The price at which the sale/purchase takes place if the option is exercised; also called the exercise price." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:date ;
